g1 = next(g for g in fx["deliveryGoldens"] if g["id"] == "fit-analysis-rejected-query-skipped-signal-during-required-render/json")
steps1 = copy.deepcopy(g1["priorSteps"]) + [{"kind": "render", "recorded": True, "outcome": "cancelled", "termination": {"class": "interrupted", "signal": "SIGINT"}}]
env1 = copy.deepcopy(g1["envelope"])
E["fit golden exact"] = admit_env(env1, "fit", steps1)
fake = {"code": "evidence.purged", "remedy": "fabricated on skipped step"}
steps_fake = copy.deepcopy(steps1)
sk = next(s for s in steps_fake if s.get("outcome") == "skipped")
sk["termination"] = dict(sk["termination"], domainDetail=fake)
e = copy.deepcopy(env1); e["errors"] = e["errors"] + [fake]
E["skipped step termination given detail; errors include it"] = admit_env(e, "fit", steps_fake)
E["skipped step termination given detail; errors exclude it"] = admit_env(copy.deepcopy(env1), "fit", steps_fake)
E["skipped fake-detail case: recorded_failure_details includes skipped?"] = any(d == fake for d in M.recorded_failure_details(steps_fake))
steps_ind = copy.deepcopy(steps1)
steps_ind.insert(1, {"kind": "query", "recorded": True, "outcome": "completed", "termination": {"class": "indeterminate", "reasonCodes": ["QUERY.COMPLETENESS_UNMET"], "domainDetail": {"code": "QUERY.VIEW_UNKNOWN", "remedy": "x"}}})
e = copy.deepcopy(env1); e["errors"] = e["errors"] + [{"code": "QUERY.VIEW_UNKNOWN", "remedy": "x"}]
