# ---- Q: executed owner query model controls
Q = chk.load("qpm_v3", ARCH / "docs/coop/design-corrections/workflows/query_projection_model.v3.py")
universe = hashlib.sha256(b"universe:rv06").hexdigest()
start = {"universe": universe, "kind": "symbol", "nativeSubjectId": "symbol:a"}
project, run = "prj1-" + hashlib.sha256(b"project:rv06").hexdigest(), "run3:" + hashlib.sha256(b"run:rv06").hexdigest()
def edges(pairs):
    return [{"confidenceMillionths": 1000000, "factId": "fact2:" + hashlib.sha256(b"rv06-%d" % i).hexdigest(), "producerClosure": "closure2:" + hashlib.sha256(b"rv06-p-%d" % i).hexdigest(),
             "relation": "references", "resolution": "resolved-binding", "source": dict(start, nativeSubjectId=a), "target": dict(start, nativeSubjectId=b)} for i, (a, b) in enumerate(pairs)]
def call(op, params, graph, bounds, size, cursor=None):
    page = {"size": size}
    if cursor:
        page["cursor"] = cursor
    return Q.traverse_projected_graph(op, params, graph, bounds=bounds, completeness="best-effort", page=page, project_id=project, run_id=run)
def law(resp, size, bounds, position):
    return M.page_law(resp["context"], len(resp["items"]), size, {k: bounds[k] for k in ("maxItemsPerOperation", "maxVisitedNodes")}, position)
def at(cursor, position):
    return cursor.rsplit(".", 1)[0] + "." + str(position)
qo = {}
cap = Q.PUBLIC_BOUNDS["maxItemsPerOperation"]
star = edges([("symbol:a", "symbol:t%06d" % i) for i in range(cap + 1)])
nparams = {"direction": "outgoing", "endpoint": start, "minResolution": "resolved-binding", "relation": "references"}
p1 = call("graph.neighbors", nparams, star, Q.PUBLIC_BOUNDS, 100)
p2 = call("graph.neighbors", nparams, star, Q.PUBLIC_BOUNDS, 100, p1["context"]["nextCursor"])
last = call("graph.neighbors", nparams, star, Q.PUBLIC_BOUNDS, 100, at(p1["context"]["nextCursor"], cap - 100))
ctxs = lambda r: {k: r["context"].get(k) for k in ("totalItems", "producedItems", "countBasis", "traversalCoverage", "truncated", "visitedNodes")} | {"cursor": "nextCursor" in r["context"], "rows": len(r["items"])}
qo["neighbors-100001-page1"] = dict(ctxs(p1), law=law(p1, 100, Q.PUBLIC_BOUNDS, 0))
qo["neighbors-100001-page2"] = dict(ctxs(p2), law=law(p2, 100, Q.PUBLIC_BOUNDS, 100))
qo["neighbors-100001-last-page@99900"] = dict(ctxs(last), law=law(last, 100, Q.PUBLIC_BOUNDS, cap - 100))
qo["page2-rows-follow-page1"] = p2["items"][0]["target"]["nativeSubjectId"] == "symbol:t%06d" % 100 and p1["items"][-1]["target"]["nativeSubjectId"] == "symbol:t%06d" % 99
for label, cur, prm in (("cursor-at-produced-end-100000", at(p1["context"]["nextCursor"], cap), nparams),
                        ("cursor-bound-to-other-params", p1["context"]["nextCursor"], dict(nparams, direction="incoming")),
                        ("cursor-malformed", "q3.zz", nparams)):
    try:
        r = call("graph.neighbors", prm, star, Q.PUBLIC_BOUNDS, 100, cur); qo["fault:" + label] = "answered " + json.dumps(ctxs(r))
    except Exception as exc:
        qo["fault:" + label] = type(exc).__name__ + ": " + " ".join(str(a) for a in getattr(exc, "args", []))[:140]
chain = edges([("symbol:c%02d" % i, "symbol:c%02d" % (i + 1)) for i in range(12)])
rstart = dict(start, nativeSubjectId="symbol:c00")
vb = dict(Q.PUBLIC_BOUNDS, maxVisitedNodes=5)
rparams = {"direction": "outgoing", "start": rstart, "minResolution": "resolved-binding", "relation": "references", "maxDepth": 12, "includeStart": False}
walk, cur, pos = [], None, 0
while True:
    r = call("graph.reach", rparams, chain, vb, 2, cur)
    walk.append(dict(ctxs(r), position=pos, law=law(r, 2, vb, pos)))
    cur = r["context"].get("nextCursor")
    if not cur:
        break
    pos += len(r["items"])
qo["reach-visited-cap-5-walk"] = walk
small = edges([("symbol:a", "symbol:s%d" % i) for i in range(7)])
walk2, cur, pos, rows = [], None, 0, []
while True:
    r = call("graph.neighbors", nparams, small, Q.PUBLIC_BOUNDS, 3, cur)
    walk2.append(dict(ctxs(r), position=pos, law=law(r, 3, Q.PUBLIC_BOUNDS, pos))); rows += r["items"]
    cur = r["context"].get("nextCursor")
    if not cur:
        break
    pos += len(r["items"])
qo["neighbors-exact-7-by-3-walk"] = walk2
qo["exact-walk-concatenation-equals-single-page"] = rows == call("graph.neighbors", nparams, small, Q.PUBLIC_BOUNDS, 100)["items"]
OUT["Q-owner-query-model"] = qo
sys.stdout.write(json.dumps(OUT, indent=1, ensure_ascii=False) + "\n")
EOF
